import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const NEW_FILES = {
 "db/migrations/core/002_roles.sql": {
  "content": "-- core/002_roles.sql  (Alua Ussenbayeva: RBAC)\n-- Four business roles instead of three. 'staff' stays so that existing users keep working.\n--   owner       everything\n--   admin       clients, visits, payments (take), knowledge base; no refunds, no settings\n--   accountant  payments (read, refund) and reports; no clients, no visits\n--   master      only the visits of his own barber card (users.master_id)\n\nALTER TABLE users DROP CONSTRAINT IF EXISTS users_role_check;\nALTER TABLE users\n  ADD CONSTRAINT users_role_check\n  CHECK (role IN ('owner', 'admin', 'accountant', 'master', 'staff'));\n\n-- The barber card (masters.master_id in the business schema, e.g. 'MS-01') this login belongs to.\nALTER TABLE users ADD COLUMN IF NOT EXISTS master_id VARCHAR(20);\n\n-- A master login without a barber card would see nobody's visits or everybody's: forbid it.\nALTER TABLE users DROP CONSTRAINT IF EXISTS users_master_link;\nALTER TABLE users\n  ADD CONSTRAINT users_master_link\n  CHECK (role <> 'master' OR master_id IS NOT NULL);\n",
  "overwrite": false
 },
 "db/migrations/tenant/009_payments_security.sql": {
  "content": "-- 009_payments_security.sql  (Alua Ussenbayeva: payment security)\n-- Applied to the schema of EVERY business (t_<id>).\n--   1. payment_refunds   : refund workflow, partial refunds, never more than was paid\n--   2. payment_requests  : idempotency keys (a repeated request returns the first answer)\n--   3. payment_events    : ids of provider webhook events already processed (replay protection)\n--   4. payments_protect_paid(): Refunded is final, and only refund records can make it Refunded\n\n-- ---------------------------------------------------------------------------\n-- 1. Refunds\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS payment_refunds (\n  refund_id   BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  payment_id  TEXT        NOT NULL REFERENCES payments (payment_id),\n  amount_kzt  INTEGER     NOT NULL CHECK (amount_kzt > 0),\n  reason      TEXT        NOT NULL CHECK (length(trim(reason)) > 0),\n  -- id of the user who did it (not the e-mail: the report role can read this table)\n  refunded_by TEXT        NOT NULL,\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS payment_refunds_payment_idx ON payment_refunds (payment_id);\n\n-- BEFORE INSERT: lock the payment row, so two refunds of the same payment can never\n-- run at the same time, then check the rules.\nCREATE OR REPLACE FUNCTION payment_refunds_guard() RETURNS trigger\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  p       payments%ROWTYPE;\n  already NUMERIC;\nBEGIN\n  SELECT * INTO p FROM payments WHERE payment_id = NEW.payment_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Payment % does not exist', NEW.payment_id\n      USING ERRCODE = 'foreign_key_violation';\n  END IF;\n  IF p.status <> 'Paid' THEN\n    RAISE EXCEPTION 'Only a Paid payment can be refunded (payment % is %)', p.payment_id, p.status\n      USING ERRCODE = 'restrict_violation';\n  END IF;\n  SELECT COALESCE(SUM(amount_kzt), 0) INTO already FROM payment_refunds WHERE payment_id = NEW.payment_id;\n  IF already + NEW.amount_kzt > p.amount_kzt THEN\n    RAISE EXCEPTION 'Refunds (% already + % now) would be more than the paid amount %', already, NEW.amount_kzt, p.amount_kzt\n      USING ERRCODE = 'check_violation';\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_payment_refunds_guard ON payment_refunds;\nCREATE TRIGGER trg_payment_refunds_guard\n  BEFORE INSERT ON payment_refunds\n  FOR EACH ROW EXECUTE FUNCTION payment_refunds_guard();\n\n-- AFTER INSERT: when the refunds add up to the whole amount, the payment becomes Refunded.\nCREATE OR REPLACE FUNCTION payment_refunds_close() RETURNS trigger\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  paid  NUMERIC;\n  total NUMERIC;\nBEGIN\n  SELECT amount_kzt INTO paid FROM payments WHERE payment_id = NEW.payment_id;\n  SELECT SUM(amount_kzt) INTO total FROM payment_refunds WHERE payment_id = NEW.payment_id;\n  IF total = paid THEN\n    UPDATE payments SET status = 'Refunded' WHERE payment_id = NEW.payment_id;\n  END IF;\n  RETURN NULL;\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_payment_refunds_close ON payment_refunds;\nCREATE TRIGGER trg_payment_refunds_close\n  AFTER INSERT ON payment_refunds\n  FOR EACH ROW EXECUTE FUNCTION payment_refunds_close();\n\n-- A refund record is a financial fact: no edit, no delete.\nCREATE OR REPLACE FUNCTION payment_refunds_immutable() RETURNS trigger\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  RAISE EXCEPTION 'payment_refunds is append-only: % is not allowed', TG_OP\n    USING ERRCODE = 'insufficient_privilege';\nEND;\n$$;\n\nDROP TRIGGER IF EXISTS trg_payment_refunds_immutable ON payment_refunds;\nCREATE TRIGGER trg_payment_refunds_immutable\n  BEFORE UPDATE OR DELETE ON payment_refunds\n  FOR EACH ROW EXECUTE FUNCTION payment_refunds_immutable();\n\n-- Every refund also goes to the audit log from migration 008.\nDROP TRIGGER IF EXISTS trg_audit_payment_refunds ON payment_refunds;\nCREATE TRIGGER trg_audit_payment_refunds\n  AFTER INSERT OR UPDATE OR DELETE ON payment_refunds\n  FOR EACH ROW EXECUTE FUNCTION audit_row_change('refund_id');\n\n-- ---------------------------------------------------------------------------\n-- 2. Idempotency keys\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS payment_requests (\n  idempotency_key UUID        PRIMARY KEY,\n  operation       TEXT        NOT NULL CHECK (operation IN ('pay', 'refund')),\n  payment_id      TEXT        NOT NULL REFERENCES payments (payment_id),\n  -- SHA-256 of what the first request asked for: the same key with another body is refused\n  request_hash    CHAR(64)    NOT NULL,\n  response        JSONB       NOT NULL,\n  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS payment_requests_payment_idx ON payment_requests (payment_id);\n\n-- ---------------------------------------------------------------------------\n-- 3. Webhook events already processed\n-- ---------------------------------------------------------------------------\nCREATE TABLE IF NOT EXISTS payment_events (\n  event_id    TEXT        PRIMARY KEY CHECK (length(event_id) BETWEEN 8 AND 100),\n  event_type  TEXT        NOT NULL,\n  payment_id  TEXT        NOT NULL REFERENCES payments (payment_id),\n  received_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- ---------------------------------------------------------------------------\n-- 4. Payment guard v2 (replaces the function from migration 008)\n-- ---------------------------------------------------------------------------\nCREATE OR REPLACE FUNCTION payments_protect_paid() RETURNS trigger\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  refunded NUMERIC;\nBEGIN\n  IF TG_OP = 'DELETE' THEN\n    IF OLD.status = 'Paid' THEN\n      RAISE EXCEPTION 'Payment % is Paid and cannot be deleted (refund it instead)', OLD.payment_id\n        USING ERRCODE = 'restrict_violation';\n    END IF;\n    RETURN OLD;\n  END IF;\n\n  -- UPDATE\n  IF OLD.status = 'Refunded' AND NEW.status <> 'Refunded' THEN\n    RAISE EXCEPTION 'Payment % was refunded: this is final', OLD.payment_id\n      USING ERRCODE = 'restrict_violation';\n  END IF;\n\n  IF OLD.status = 'Paid'\n     AND (NEW.amount_kzt IS DISTINCT FROM OLD.amount_kzt\n          OR NEW.appointment_id IS DISTINCT FROM OLD.appointment_id) THEN\n    RAISE EXCEPTION 'Payment % is Paid: amount and visit cannot be changed', OLD.payment_id\n      USING ERRCODE = 'restrict_violation';\n  END IF;\n\n  -- A Paid payment becomes Refunded only when refund records cover the whole amount.\n  IF OLD.status = 'Paid' AND NEW.status = 'Refunded' THEN\n    SELECT COALESCE(SUM(amount_kzt), 0) INTO refunded FROM payment_refunds WHERE payment_id = OLD.payment_id;\n    IF refunded < OLD.amount_kzt THEN\n      RAISE EXCEPTION 'Payment % cannot become Refunded: refund records cover only % of %', OLD.payment_id, refunded, OLD.amount_kzt\n        USING ERRCODE = 'restrict_violation';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n",
  "overwrite": false
 },
 "db/checks/payments_check.sql": {
  "content": "-- db/checks/payments_check.sql  (Alua Ussenbayeva)\n-- Run:  psql \"$DATABASE_URL\" -v schema=t_<id> -f db/checks/payments_check.sql\n-- Checks migration 009 (refunds, idempotency keys, webhook events). Ends with ROLLBACK.\n\n\\set ON_ERROR_STOP off\nBEGIN;\nSELECT set_config('search_path', format('%I, public', :'schema'), true);\n\n\\echo '=== R1-R6: refund workflow on one Paid payment ==='\nDO $$\nDECLARE\n  pid  TEXT;\n  amt  INTEGER;\n  st   TEXT;\nBEGIN\n  SELECT payment_id, amount_kzt::int INTO pid, amt FROM payments WHERE status = 'Paid' AND amount_kzt >= 2 LIMIT 1;\n  IF pid IS NULL THEN RAISE NOTICE 'SKIP: no Paid payment in demo data'; RETURN; END IF;\n\n  -- R1: a partial refund is allowed, the payment stays Paid\n  INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES (pid, 1, 'check', 'check');\n  SELECT status INTO st FROM payments WHERE payment_id = pid;\n  IF st = 'Paid' THEN RAISE NOTICE 'OK R1: partial refund of 1 KZT, payment stays Paid';\n  ELSE RAISE NOTICE 'FAIL R1: status is % after a partial refund', st; END IF;\n\n  -- R2: more than what is left is refused\n  BEGIN\n    INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES (pid, amt, 'too much', 'check');\n    RAISE NOTICE 'FAIL R2: refund above the paid amount was accepted';\n  EXCEPTION WHEN check_violation THEN\n    RAISE NOTICE 'OK R2: refused -> %', SQLERRM;\n  END;\n\n  -- R3: the rest of the money closes the payment as Refunded\n  INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES (pid, amt - 1, 'check rest', 'check');\n  SELECT status INTO st FROM payments WHERE payment_id = pid;\n  IF st = 'Refunded' THEN RAISE NOTICE 'OK R3: refunds add up to the whole amount, payment became Refunded';\n  ELSE RAISE NOTICE 'FAIL R3: status is % after full refund', st; END IF;\n\n  -- R4: a refunded payment cannot be refunded again\n  BEGIN\n    INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES (pid, 1, 'again', 'check');\n    RAISE NOTICE 'FAIL R4: a Refunded payment was refunded again';\n  EXCEPTION WHEN restrict_violation THEN\n    RAISE NOTICE 'OK R4: refused -> %', SQLERRM;\n  END;\n\n  -- R5: refund records cannot be edited or deleted\n  BEGIN\n    UPDATE payment_refunds SET reason = 'edited' WHERE payment_id = pid;\n    RAISE NOTICE 'FAIL R5: refund record was edited';\n  EXCEPTION WHEN insufficient_privilege THEN\n    RAISE NOTICE 'OK R5: UPDATE refused -> %', SQLERRM;\n  END;\n\n  -- R6: Refunded is final\n  BEGIN\n    UPDATE payments SET status = 'Paid' WHERE payment_id = pid;\n    RAISE NOTICE 'FAIL R6: Refunded payment went back to Paid';\n  EXCEPTION WHEN restrict_violation THEN\n    RAISE NOTICE 'OK R6: refused -> %', SQLERRM;\n  END;\nEND $$;\n\n\\echo '=== R7: a Pending payment cannot be refunded as money ==='\nDO $$\nDECLARE pid TEXT;\nBEGIN\n  SELECT payment_id INTO pid FROM payments WHERE status = 'Pending' LIMIT 1;\n  IF pid IS NULL THEN RAISE NOTICE 'SKIP: no Pending payment in demo data'; RETURN; END IF;\n  BEGIN\n    INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES (pid, 1, 'check', 'check');\n    RAISE NOTICE 'FAIL R7: refund of an unpaid payment was accepted';\n  EXCEPTION WHEN restrict_violation THEN\n    RAISE NOTICE 'OK R7: refused -> %', SQLERRM;\n  END;\nEND $$;\n\n\\echo '=== R8: a Paid payment cannot be set to Refunded without refund records ==='\nDO $$\nDECLARE pid TEXT;\nBEGIN\n  SELECT payment_id INTO pid FROM payments WHERE status = 'Paid' LIMIT 1;\n  IF pid IS NULL THEN RAISE NOTICE 'SKIP: no Paid payment in demo data'; RETURN; END IF;\n  BEGIN\n    UPDATE payments SET status = 'Refunded' WHERE payment_id = pid;\n    RAISE NOTICE 'FAIL R8: status was changed to Refunded by hand';\n  EXCEPTION WHEN restrict_violation THEN\n    RAISE NOTICE 'OK R8: refused -> %', SQLERRM;\n  END;\nEND $$;\n\n\\echo '=== I1: the same idempotency key cannot be stored twice ==='\nDO $$\nDECLARE pid TEXT;\nBEGIN\n  SELECT payment_id INTO pid FROM payments LIMIT 1;\n  INSERT INTO payment_requests (idempotency_key, operation, payment_id, request_hash, response)\n  VALUES ('11111111-1111-1111-1111-111111111111', 'pay', pid, repeat('a', 64), '{}'::jsonb);\n  BEGIN\n    INSERT INTO payment_requests (idempotency_key, operation, payment_id, request_hash, response)\n    VALUES ('11111111-1111-1111-1111-111111111111', 'pay', pid, repeat('b', 64), '{}'::jsonb);\n    RAISE NOTICE 'FAIL I1: duplicate key was stored';\n  EXCEPTION WHEN unique_violation THEN\n    RAISE NOTICE 'OK I1: duplicate key refused';\n  END;\nEND $$;\n\n\\echo '=== E1: the same webhook event id cannot be stored twice ==='\nDO $$\nDECLARE pid TEXT;\nBEGIN\n  SELECT payment_id INTO pid FROM payments LIMIT 1;\n  INSERT INTO payment_events (event_id, event_type, payment_id) VALUES ('evt_check_0001', 'payment.succeeded', pid);\n  BEGIN\n    INSERT INTO payment_events (event_id, event_type, payment_id) VALUES ('evt_check_0001', 'payment.succeeded', pid);\n    RAISE NOTICE 'FAIL E1: duplicate event was stored';\n  EXCEPTION WHEN unique_violation THEN\n    RAISE NOTICE 'OK E1: duplicate event refused (replay protection)';\n  END;\nEND $$;\n\nROLLBACK;\n\\echo '=== done: ROLLBACK, demo data unchanged ==='\n",
  "overwrite": false
 },
 "apps/api/src/auth/rbac-policy.ts": {
  "content": "// Who may do what. Pure data and functions (no Express, no database), so it is easy to test.\n\nexport type Role = \"owner\" | \"admin\" | \"accountant\" | \"master\" | \"staff\";\n\nconst ALL_PERMISSIONS = [\n  \"clients:read\",\n  \"clients:write\",\n  \"appointments:read\", // all visits\n  \"appointments:own\", // only the visits of the master's own barber card\n  \"appointments:write\",\n  \"payments:read\",\n  \"payments:pay\", // mark paid, take a full payment\n  \"payments:refund\",\n  \"knowledge:read\",\n  \"knowledge:write\",\n  \"reports:read\",\n  \"import:manage\",\n  \"integrations:manage\",\n  \"sql:console\",\n  \"users:manage\",\n] as const;\n\nexport type Permission = (typeof ALL_PERMISSIONS)[number];\n\nconst FRONT_DESK: readonly Permission[] = [\n  \"clients:read\",\n  \"clients:write\",\n  \"appointments:read\",\n  \"appointments:write\",\n  \"payments:read\",\n  \"payments:pay\",\n  \"knowledge:read\",\n  \"knowledge:write\",\n  \"reports:read\",\n  \"import:manage\",\n];\n\nexport const ROLE_PERMISSIONS: Record<Role, readonly Permission[]> = {\n  owner: ALL_PERMISSIONS,\n  admin: FRONT_DESK,\n  // 'staff' is the old role from before RBAC: it keeps the front-desk rights.\n  staff: FRONT_DESK,\n  accountant: [\"payments:read\", \"payments:refund\", \"reports:read\"],\n  master: [\"appointments:own\"],\n};\n\nexport function can(role: string | undefined, permission: Permission): boolean {\n  if (!role) return false;\n  const list = (ROLE_PERMISSIONS as Record<string, readonly Permission[] | undefined>)[role];\n  return list ? list.includes(permission) : false;\n}\n\n/** A master sees only the visits of his own barber card; everybody else sees all rows. */\nexport function ownRowsOnly<T>(user: { role?: string; master_id?: string | null } | undefined, rows: T[]): T[] {\n  if (user?.role !== \"master\") return rows;\n  return rows.filter((r) => (r as { master_id?: string }).master_id === user.master_id);\n}\n",
  "overwrite": false
 },
 "apps/api/src/auth/rbac.ts": {
  "content": "import type { RequestHandler } from \"express\";\nimport { config } from \"../config.js\";\nimport { HttpError } from \"../lib/errors.js\";\nimport { logger } from \"../lib/logger.js\";\nimport { can, type Permission } from \"./rbac-policy.js\";\n\n/**\n * Lets the request through when the signed-in user's role has ANY of the permissions.\n * Sign-in itself is checked earlier by requireAuth: a request without req.user here is\n * a public path (calendar feed) or the test setup, so it is not judged by role.\n * Every refusal is written to the log (who, which role, which path).\n */\nexport function requirePermission(...anyOf: Permission[]): RequestHandler {\n  return (req, _res, next) => {\n    if (!config.AUTH_REQUIRED || !req.user) return next();\n    if (anyOf.some((p) => can(req.user!.role, p))) return next();\n    logger.warn({ user: req.user.id, role: req.user.role, needs: anyOf, method: req.method, path: req.path }, \"access denied by role\");\n    next(new HttpError(403, \"Your role is not allowed to do this.\", \"forbidden\"));\n  };\n}\n",
  "overwrite": false
 },
 "apps/api/src/lib/idempotency.ts": {
  "content": "import type { Request } from \"express\";\nimport { HttpError } from \"./errors.js\";\n\nconst UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\n\n/** Reads the Idempotency-Key header (a UUID the client makes once per button press). */\nexport function readIdempotencyKey(req: Request): string | undefined {\n  const raw = req.get(\"idempotency-key\");\n  if (raw === undefined) return undefined;\n  if (!UUID.test(raw)) throw new HttpError(400, \"Idempotency-Key must be a UUID.\", \"bad_request\");\n  return raw.toLowerCase();\n}\n",
  "overwrite": false
 },
 "apps/api/src/lib/payment-signature.ts": {
  "content": "import { createHmac, timingSafeEqual } from \"node:crypto\";\n\nexport type SignatureVerdict = \"ok\" | \"missing\" | \"stale\" | \"bad_signature\";\n\n/**\n * How the bank puts the signature into the request:\n *   voronix  x-voronix-timestamp + x-voronix-signature (our own simple format, used by the simulator)\n *   stripe   one header \"stripe-signature: t=<unix seconds>,v1=<hex>[,v1=<hex>]\" (the format Stripe documents)\n * Both sign the same thing: HMAC-SHA256 over \"<timestamp>.<raw body>\". A real bank with another\n * format gets its own branch in readSignatureHeaders; the checking below does not change.\n */\nexport type SignatureScheme = \"voronix\" | \"stripe\";\n\n/** How far the timestamp may be from our clock. A recorded request older than this is refused. */\nexport const TOLERANCE_SECONDS = 300;\n\n/** HMAC-SHA256 over \"<timestamp>.<raw body>\", as hex. The bank signs the same way. */\nexport function signPayload(secret: string, timestamp: string, raw: Buffer | string): string {\n  return createHmac(\"sha256\", secret).update(`${timestamp}.`).update(raw).digest(\"hex\");\n}\n\n/** Takes the timestamp and the signature(s) out of the headers of the chosen scheme. */\nexport function readSignatureHeaders(\n  scheme: SignatureScheme,\n  header: (name: string) => string | undefined,\n): { timestamp: string | undefined; signatures: string[] } {\n  if (scheme === \"stripe\") {\n    const value = header(\"stripe-signature\");\n    let timestamp: string | undefined;\n    const signatures: string[] = [];\n    for (const part of (value ?? \"\").split(\",\")) {\n      const eq = part.indexOf(\"=\");\n      if (eq < 0) continue;\n      const key = part.slice(0, eq).trim();\n      const val = part.slice(eq + 1).trim();\n      if (key === \"t\") timestamp = val;\n      else if (key === \"v1\") signatures.push(val); // several v1 values appear while a secret is rotated\n    }\n    return { timestamp, signatures };\n  }\n  const signature = header(\"x-voronix-signature\");\n  return { timestamp: header(\"x-voronix-timestamp\"), signatures: signature ? [signature] : [] };\n}\n\n/**\n * Accepts the request if ANY of our secrets (the current one and, during rotation, the previous one)\n * produces ANY of the signatures sent. The comparison is constant-time.\n */\nexport function verifyPaymentSignature(input: {\n  secret: string | string[];\n  raw: Buffer | undefined; // the exact bytes that arrived, not re-serialised JSON\n  timestamp: string | undefined;\n  signature: string | string[] | undefined;\n  now?: number; // unix seconds, for tests\n  toleranceSeconds?: number;\n}): SignatureVerdict {\n  const { raw, timestamp } = input;\n  const secrets = (Array.isArray(input.secret) ? input.secret : [input.secret]).filter(Boolean);\n  const signatures = Array.isArray(input.signature) ? input.signature : input.signature ? [input.signature] : [];\n  if (!raw || !timestamp || !signatures.length || !secrets.length) return \"missing\";\n  if (!/^\\d{10}$/.test(timestamp)) return \"bad_signature\";\n\n  let matched = false;\n  for (const secret of secrets) {\n    const expected = Buffer.from(signPayload(secret, timestamp, raw), \"hex\");\n    for (const sig of signatures) {\n      const given = Buffer.from(sig, \"hex\");\n      if (given.length === expected.length && timingSafeEqual(expected, given)) matched = true;\n    }\n  }\n  if (!matched) return \"bad_signature\";\n\n  const now = input.now ?? Math.floor(Date.now() / 1000);\n  if (Math.abs(now - Number(timestamp)) > (input.toleranceSeconds ?? TOLERANCE_SECONDS)) return \"stale\";\n  return \"ok\";\n}\n",
  "overwrite": false
 },
 "apps/api/src/routes/payment-webhook.routes.ts": {
  "content": "import { Router, type Request } from \"express\";\nimport { z } from \"zod\";\nimport { replyTo } from \"../ai/runner.js\";\nimport { pool } from \"../db/pool.js\";\nimport { HttpError, notFound } from \"../lib/errors.js\";\nimport { logger } from \"../lib/logger.js\";\nimport { readSignatureHeaders, verifyPaymentSignature, type SignatureScheme } from \"../lib/payment-signature.js\";\nimport * as pays from \"../repositories/payments.repo.js\";\nimport * as booking from \"../services/booking.service.js\";\nimport { withTenant } from \"../tenancy/context.js\";\nimport { findTenant } from \"../tenancy/tenants.js\";\n\nexport const paymentWebhookRouter = Router();\n\n/**\n * What the payment provider sends. Real providers use their own field names and their own\n * signature scheme: map them here after reading the provider's documentation.\n */\nconst PaymentEvent = z.object({\n  event_id: z.string().min(8).max(100),\n  type: z.string().min(1).max(60),\n  payment_id: z.string().regex(/^PM-\\d+$/),\n  amount_kzt: z.number().int().positive(),\n});\n\n/**\n * POST /api/channels/:business/payments/webhook   (public path: there is no browser session,\n * the signature is the proof). The signature is an HMAC-SHA256 of \"<timestamp>.<raw body>\" made\n * with PAYMENT_WEBHOOK_SECRET; PAYMENT_WEBHOOK_SCHEME picks how the bank sends it (voronix | stripe).\n * Not here yet: the body of a real bank has its own field names, so map them in PaymentEvent.\n */\npaymentWebhookRouter.post(\"/channels/:business/payments/webhook\", async (req: Request, res) => {\n  // The current secret and, while it is being rotated, the previous one (both accepted).\n  const secrets = [process.env.PAYMENT_WEBHOOK_SECRET, process.env.PAYMENT_WEBHOOK_SECRET_PREVIOUS].filter((s): s is string => !!s);\n  if (!secrets.length) throw new HttpError(404, \"Payment webhook is not configured\", \"not_found\");\n  const scheme: SignatureScheme = process.env.PAYMENT_WEBHOOK_SCHEME === \"stripe\" ? \"stripe\" : \"voronix\";\n\n  const { timestamp, signatures } = readSignatureHeaders(scheme, (name) => req.get(name));\n  const verdict = verifyPaymentSignature({\n    secret: secrets,\n    raw: (req as Request & { rawBody?: Buffer }).rawBody,\n    timestamp,\n    signature: signatures,\n  });\n  if (verdict !== \"ok\") {\n    logger.warn({ verdict, scheme, business: req.params.business }, \"payment webhook rejected\");\n    throw new HttpError(401, \"Bad signature\", \"unauthorized\"); // same answer for every reason\n  }\n\n  const tenant = await findTenant(String(req.params.business));\n  if (!tenant) throw notFound(\"Business\");\n  const event = PaymentEvent.parse(req.body);\n\n  const result = await withTenant(tenant, () => handleEvent(event));\n  res.status(200).json(result); // 2xx also for duplicates, so the provider stops retrying\n});\n\nasync function handleEvent(event: z.infer<typeof PaymentEvent>): Promise<{ status: string }> {\n  if (event.type !== \"payment.succeeded\") return { status: \"ignored\" };\n\n  const payment = await pays.getPayment(pool, event.payment_id, false);\n  if (!payment) throw notFound(\"Payment\");\n  // A true signature does not prove the amount is right: compare it with our own record.\n  if (Number(payment.amount_kzt) !== event.amount_kzt) {\n    logger.warn({ payment: event.payment_id }, \"payment webhook amount does not match\");\n    throw new HttpError(422, \"Amount does not match the payment\", \"amount_mismatch\");\n  }\n\n  // Claim the event id first: the same event arriving twice (or in parallel) is processed once.\n  const claim = await pool.query(\n    `INSERT INTO payment_events (event_id, event_type, payment_id) VALUES ($1, $2, $3)\n     ON CONFLICT (event_id) DO NOTHING RETURNING event_id`,\n    [event.event_id, event.type, event.payment_id],\n  );\n  if (!claim.rowCount) return { status: \"duplicate\" };\n\n  try {\n    const { conversations } = await booking.markPaid(event.payment_id, \"Payment provider\");\n    for (const id of conversations) {\n      const { rows } = await pool.query<{ ai_enabled: boolean }>(`SELECT ai_enabled FROM conversations WHERE conversation_id = $1`, [id]);\n      if (rows[0]?.ai_enabled) void replyTo(id);\n    }\n    return { status: \"processed\" };\n  } catch (err) {\n    // Processing failed: release the claim so the provider's retry can try again.\n    await pool.query(`DELETE FROM payment_events WHERE event_id = $1`, [event.event_id]);\n    throw err;\n  }\n}\n",
  "overwrite": false
 },
 "apps/api/test/unit/rbac.test.ts": {
  "content": "import { describe, expect, it } from \"vitest\";\nimport { can, ownRowsOnly } from \"../../src/auth/rbac-policy.js\";\n\ndescribe(\"roles (RBAC)\", () => {\n  it(\"the owner can do everything\", () => {\n    for (const p of [\"clients:read\", \"payments:refund\", \"integrations:manage\", \"sql:console\", \"users:manage\"] as const) {\n      expect(can(\"owner\", p)).toBe(true);\n    }\n  });\n\n  it(\"the administrator works with clients and takes payments, but cannot refund or change settings\", () => {\n    expect(can(\"admin\", \"clients:write\")).toBe(true);\n    expect(can(\"admin\", \"payments:pay\")).toBe(true);\n    expect(can(\"admin\", \"payments:refund\")).toBe(false);\n    expect(can(\"admin\", \"integrations:manage\")).toBe(false);\n    expect(can(\"admin\", \"sql:console\")).toBe(false);\n  });\n\n  it(\"the accountant refunds and reads payments, but sees no clients and takes no payments\", () => {\n    expect(can(\"accountant\", \"payments:read\")).toBe(true);\n    expect(can(\"accountant\", \"payments:refund\")).toBe(true);\n    expect(can(\"accountant\", \"payments:pay\")).toBe(false);\n    expect(can(\"accountant\", \"clients:read\")).toBe(false);\n    expect(can(\"accountant\", \"appointments:read\")).toBe(false);\n  });\n\n  it(\"the master only has the right to his own visits\", () => {\n    expect(can(\"master\", \"appointments:own\")).toBe(true);\n    expect(can(\"master\", \"appointments:read\")).toBe(false);\n    expect(can(\"master\", \"payments:read\")).toBe(false);\n    expect(can(\"master\", \"clients:read\")).toBe(false);\n  });\n\n  it(\"the old 'staff' role keeps the front-desk rights, an unknown role gets nothing\", () => {\n    expect(can(\"staff\", \"clients:read\")).toBe(true);\n    expect(can(\"staff\", \"payments:refund\")).toBe(false);\n    expect(can(\"hacker\", \"clients:read\")).toBe(false);\n    expect(can(undefined, \"clients:read\")).toBe(false);\n  });\n\n  it(\"a master sees only the rows of his barber card, everybody else sees all\", () => {\n    const rows = [{ id: \"AP-1\", master_id: \"MS-01\" }, { id: \"AP-2\", master_id: \"MS-02\" }];\n    expect(ownRowsOnly({ role: \"master\", master_id: \"MS-01\" }, rows)).toEqual([rows[0]]);\n    expect(ownRowsOnly({ role: \"admin\" }, rows)).toEqual(rows);\n    expect(ownRowsOnly(undefined, rows)).toEqual(rows);\n  });\n});\n",
  "overwrite": false
 },
 "apps/api/test/unit/payment-signature.test.ts": {
  "content": "import { describe, expect, it } from \"vitest\";\nimport { readSignatureHeaders, signPayload, verifyPaymentSignature } from \"../../src/lib/payment-signature.js\";\n\nconst secret = \"test-secret-not-real\";\nconst now = 1_800_000_000;\nconst ts = String(now);\nconst body = Buffer.from(JSON.stringify({ event_id: \"evt_00000001\", type: \"payment.succeeded\", payment_id: \"PM-00001\", amount_kzt: 6600 }));\n\ndescribe(\"payment webhook signature\", () => {\n  it(\"accepts a correct signature\", () => {\n    const signature = signPayload(secret, ts, body);\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature, now })).toBe(\"ok\");\n  });\n\n  it(\"refuses a body that was changed after signing (for example another amount)\", () => {\n    const signature = signPayload(secret, ts, body);\n    const forged = Buffer.from(body.toString().replace(\"6600\", \"1\"));\n    expect(verifyPaymentSignature({ secret, raw: forged, timestamp: ts, signature, now })).toBe(\"bad_signature\");\n  });\n\n  it(\"refuses a signature made with another secret\", () => {\n    const signature = signPayload(\"another-secret\", ts, body);\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature, now })).toBe(\"bad_signature\");\n  });\n\n  it(\"refuses a recorded request that is replayed later\", () => {\n    const signature = signPayload(secret, ts, body);\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature, now: now + 301 })).toBe(\"stale\");\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature, now: now + 299 })).toBe(\"ok\");\n  });\n\n  it(\"refuses requests without signature headers or with a garbage signature\", () => {\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: undefined, signature: undefined, now })).toBe(\"missing\");\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature: \"zz\", now })).toBe(\"bad_signature\");\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp: ts, signature: [], now })).toBe(\"missing\");\n  });\n\n  it(\"during secret rotation the previous secret is still accepted, and an unknown one is not\", () => {\n    const old = signPayload(\"old-secret\", ts, body);\n    expect(verifyPaymentSignature({ secret: [\"new-secret\", \"old-secret\"], raw: body, timestamp: ts, signature: old, now })).toBe(\"ok\");\n    expect(verifyPaymentSignature({ secret: [\"new-secret\"], raw: body, timestamp: ts, signature: old, now })).toBe(\"bad_signature\");\n  });\n});\n\ndescribe(\"signature headers of the bank\", () => {\n  const headers = (h: Record<string, string>) => (name: string) => h[name.toLowerCase()];\n\n  it(\"reads our own format\", () => {\n    const got = readSignatureHeaders(\"voronix\", headers({ \"x-voronix-timestamp\": ts, \"x-voronix-signature\": \"ab12\" }));\n    expect(got).toEqual({ timestamp: ts, signatures: [\"ab12\"] });\n  });\n\n  it(\"reads the Stripe-style header with several v1 signatures (secret rotation at the bank)\", () => {\n    const got = readSignatureHeaders(\"stripe\", headers({ \"stripe-signature\": `t=${ts},v1=aaaa,v0=ignored,v1=bbbb` }));\n    expect(got).toEqual({ timestamp: ts, signatures: [\"aaaa\", \"bbbb\"] });\n  });\n\n  it(\"a Stripe-style request verifies end to end\", () => {\n    const sig = signPayload(secret, ts, body);\n    const { timestamp, signatures } = readSignatureHeaders(\"stripe\", headers({ \"stripe-signature\": `t=${ts},v1=${sig}` }));\n    expect(verifyPaymentSignature({ secret, raw: body, timestamp, signature: signatures, now })).toBe(\"ok\");\n  });\n\n  it(\"missing headers give nothing to verify\", () => {\n    expect(readSignatureHeaders(\"voronix\", headers({}))).toEqual({ timestamp: undefined, signatures: [] });\n    expect(readSignatureHeaders(\"stripe\", headers({}))).toEqual({ timestamp: undefined, signatures: [] });\n  });\n});\n",
  "overwrite": false
 },
 "apps/api/src/routes/crm.routes.ts": {
  "content": "import { Router } from \"express\";\nimport { z } from \"zod\";\nimport { requirePermission } from \"../auth/rbac.js\";\nimport { ownRowsOnly } from \"../auth/rbac-policy.js\";\nimport { pool } from \"../db/pool.js\";\nimport { readIdempotencyKey } from \"../lib/idempotency.js\";\nimport { notFound } from \"../lib/errors.js\";\nimport { bus } from \"../realtime/bus.js\";\nimport * as appts from \"../repositories/appointments.repo.js\";\nimport * as clients from \"../repositories/clients.repo.js\";\nimport * as knowledge from \"../repositories/knowledge.repo.js\";\nimport { listPayments } from \"../repositories/payments.repo.js\";\nimport * as booking from \"../services/booking.service.js\";\nimport { replyTo } from \"../ai/runner.js\";\nimport { AppointmentBody, ClientBody, KnowledgeBody, SlotsQuery, StatusBody } from \"./schemas.js\";\n\nexport const crmRouter = Router();\n\n/** Optional body of a refund: without it the whole remaining amount is refunded. */\nconst RefundBody = z.object({\n  amount_kzt: z.number().int().positive().optional(),\n  reason: z.string().trim().min(3).max(200).optional(),\n});\n\n/* clients */\ncrmRouter.get(\"/clients\", requirePermission(\"clients:read\"), async (_req, res) => {\n  res.json(await clients.listClients(pool));\n});\ncrmRouter.get(\"/client-channels\", requirePermission(\"clients:read\"), async (_req, res) => {\n  res.json(await clients.listChannels(pool));\n});\ncrmRouter.post(\"/clients\", requirePermission(\"clients:write\"), async (req, res) => {\n  const c = await clients.createClient(pool, ClientBody.parse(req.body));\n  bus.changed(\"clients\");\n  res.status(201).json(c);\n});\ncrmRouter.patch(\"/clients/:id\", requirePermission(\"clients:write\"), async (req, res) => {\n  const c = await clients.updateClient(pool, req.params.id, ClientBody.partial().parse(req.body));\n  if (!c) throw notFound(\"Client\");\n  bus.changed(\"clients\");\n  res.json(c);\n});\n\n/* appointments */\ncrmRouter.get(\"/appointments\", requirePermission(\"appointments:read\", \"appointments:own\"), async (req, res) => {\n  const q = req.query as Record<string, string | undefined>;\n  const rows = await appts.listAppointments(pool, { from: q.from, to: q.to, client_id: q.client_id });\n  res.json(ownRowsOnly(req.user, rows)); // a master gets only his own visits\n});\ncrmRouter.get(\"/appointments/free-slots\", requirePermission(\"appointments:read\"), async (req, res) => {\n  const q = SlotsQuery.parse(req.query);\n  res.json(await booking.findFreeSlots(pool, q.service_code, q.date, q.master_id));\n});\ncrmRouter.post(\"/appointments\", requirePermission(\"appointments:write\"), async (req, res) => {\n  const body = AppointmentBody.parse(req.body);\n  res.status(201).json(await booking.createBooking({ ...body, source: \"Admin\" }, { strict: false }));\n});\ncrmRouter.put(\"/appointments/:id\", requirePermission(\"appointments:write\"), async (req, res) => {\n  res.json(await booking.updateBooking(req.params.id, AppointmentBody.parse(req.body)));\n});\ncrmRouter.patch(\"/appointments/:id/status\", requirePermission(\"appointments:write\"), async (req, res) => {\n  res.json(await booking.changeStatus(req.params.id, StatusBody.parse(req.body).status));\n});\n\n/* payments */\ncrmRouter.get(\"/payments\", requirePermission(\"payments:read\"), async (_req, res) => {\n  res.json(await listPayments(pool));\n});\n/** Client paid (demo payment button, or a payment provider webhook). Header Idempotency-Key makes a repeat safe. */\ncrmRouter.post(\"/payments/:id/pay\", requirePermission(\"payments:pay\"), async (req, res) => {\n  const { payment, conversations } = await booking.markPaid(\n    req.params.id,\n    req.body?.method ?? booking.defaultPayMethod(),\n    undefined,\n    readIdempotencyKey(req),\n  );\n  res.json(payment);\n  for (const id of conversations) {\n    const { rows } = await pool.query<{ ai_enabled: boolean }>(`SELECT ai_enabled FROM conversations WHERE conversation_id = $1`, [id]);\n    if (rows[0]?.ai_enabled) void replyTo(id);\n  }\n});\ncrmRouter.post(\"/payments/:id/refund\", requirePermission(\"payments:refund\"), async (req, res) => {\n  const body = RefundBody.parse(req.body ?? {});\n  res.json(await booking.refund(req.params.id, { ...body, by: req.user?.id, idempotencyKey: readIdempotencyKey(req) }));\n});\ncrmRouter.post(\"/appointments/:id/full-payment\", requirePermission(\"payments:pay\"), async (req, res) => {\n  res.status(201).json(await booking.takeFullPayment(req.params.id, req.body?.method ?? \"Card\"));\n});\n\n/* knowledge base */\ncrmRouter.get(\"/knowledge\", requirePermission(\"knowledge:read\"), async (_req, res) => {\n  res.json(await knowledge.listKnowledge(pool));\n});\ncrmRouter.post(\"/knowledge\", requirePermission(\"knowledge:write\"), async (req, res) => {\n  const k = await knowledge.createKnowledge(pool, KnowledgeBody.parse(req.body));\n  bus.changed(\"knowledge\");\n  res.status(201).json(k);\n});\ncrmRouter.put(\"/knowledge/:id\", requirePermission(\"knowledge:write\"), async (req, res) => {\n  const k = await knowledge.updateKnowledge(pool, req.params.id, KnowledgeBody.parse(req.body));\n  if (!k) throw notFound(\"Knowledge entry\");\n  bus.changed(\"knowledge\");\n  res.json(k);\n});\ncrmRouter.delete(\"/knowledge/:id\", requirePermission(\"knowledge:write\"), async (req, res) => {\n  if (!(await knowledge.deleteKnowledge(pool, req.params.id))) throw notFound(\"Knowledge entry\");\n  bus.changed(\"knowledge\");\n  res.status(204).end();\n});\n",
  "overwrite": true
 },
 "docs/security-architecture.md": {
  "content": "# VoroniX: database security architecture\n\nOwner: Alua Ussenbayeva (architecture & security, database Scrum master)\n\n## 1. Defence in depth: the path of one client message\n\n```\nClient (Telegram / WhatsApp / Instagram)\n   |  1. webhook secret: a request without the secret is refused\n   v\nAPI (Node.js + TypeScript)\n   |  2. validation of input (dates, ids), error mapping (lib/errors.ts)\n   v\nAI administrator\n   |  3. 8 fixed tools, never SQL; same booking service as the admin screen\n   v\nPostgreSQL\n   |  4. roles: crm_readonly (no master_accounts, integrations, audit_log)\n   |  5. constraints: PK, FK, NOT NULL, CHECK, EXCLUDE, triggers\n   |  6. audit_log: every change of clients, appointments, payments\n   v\nBackup / secrets\n      7. integration tokens encrypted by the app, keys rotated (Amirkhan)\n```\n\nIf one layer fails, the next one still protects the data. This is the main\narchitecture idea: security is not one wall but seven.\n\n## 2. Threats and controls\n\n| # | Threat | Control | Where | Status |\n|---|--------|---------|-------|--------|\n| T1 | Someone edits a payment after it is Paid | trigger `payments_protect_paid` | tenant/008_security_audit.sql | done |\n| T2 | Nobody knows who changed a visit or a payment | `audit_log` + triggers | tenant/008_security_audit.sql | done |\n| T3 | An insider deletes the audit trail | append-only trigger, no access for report role | tenant/008_security_audit.sql | done |\n| T4 | A report user changes or reads secrets | role `crm_readonly`, READ ONLY transaction, 3 s timeout | Task 9 | done |\n| T5 | The AI is tricked into showing other clients' data | AI uses fixed tools, not SQL | Task 9 | done |\n| T6 | Garbage phone numbers break matching of clients | `clients_phone_format` CHECK | tenant/008_security_audit.sql | done |\n| T7 | Tokens read from a database backup | application-level encryption with key rotation (INTEGRATION_ENCRYPTION_KEYS) | Amirkhan | done (his part) |\n| T8 | Secrets or IDE files committed to the public repository | `.gitignore`, secret scan of history | repo | to do |\n| T9 | One shared login for all barbers | separate login per barber, least privilege | next sprint | planned |\n| T10 | Report role reads audit_log (phones of clients) through the blanket `GRANT SELECT ON ALL TABLES` | `audit_log` added to the REVOKE list in `migrate.ts`; test T6 in security_check.sql | migrate.ts, security_check.sql | done (found by T6) |\n| T11 | SQL console or demo reset left on in production | `SQL_CONSOLE` and `ALLOW_DEMO_RESET` are off by default in production | .env.example | done (configuration) |\n\n## 3. Decisions and why\n\n- **master_accounts and integrations are not audited.** The audit row would copy\n  `password_hash` and tokens into another table and create a second secret store.\n- **One audit_log per business schema.** The migration runs in every `t_<id>` schema,\n  so audit rows of one business can never mix with another business (ADR-7).\n- **Phone is optional, but its format is checked.** Instagram gives no phone, so\n  NOT NULL would block real clients; a format rule still stops garbage.\n- **Paid payments are refunded, not deleted.** Money history must stay complete.\n\n## 4. How to verify\n\n```\npsql \"$DATABASE_URL\" -f db/checks/security_check.sql\n```\n\nSix tests print OK/FAIL; the script ends with ROLLBACK, demo data stays unchanged.\n\n## 5. Roles (RBAC)\n\nRoles live in `public.users.role`; the rules are in `apps/api/src/auth/rbac-policy.ts`\nand are enforced on every API route by `requirePermission(...)`. Every refusal is logged.\n\n| Action | owner | admin | accountant | master |\n|--------|:-----:|:-----:|:----------:|:------:|\n| Settings, integrations, SQL console | yes | no | no | no |\n| Clients | yes | yes | no | no |\n| Visits | all | all | no | only own (users.master_id) |\n| Take a payment | yes | yes | no | no |\n| Read payments, reports | yes | yes | yes | no |\n| Refund | yes | no | yes | no |\n\nThe old role `staff` keeps the administrator rights. Authentication stays in one place\n(`requireAuth`); role checks only judge users that are already signed in.\n\n## 6. Payment security\n\n| # | Threat | Control | Where |\n|---|--------|---------|-------|\n| T12 | Refund of more money than was paid, or two refunds at the same moment | `payment_refunds`: trigger locks the payment row (`FOR UPDATE`) and checks the sum | tenant/009 |\n| T13 | Someone sets a payment to Refunded by hand, or brings a Refunded one back | `payments_protect_paid()` v2: only refund records can make it Refunded; Refunded is final | tenant/009 |\n| T14 | A double click or a network retry pays twice | `Idempotency-Key` header, table `payment_requests`; the same key with another body gives 422 | booking.service.ts |\n| T15 | A fake \"payment successful\" request | HMAC-SHA256 over `timestamp.body`, 5-minute window, unique `event_id`, amount compared with our record, previous secret accepted during rotation | payment-webhook.routes.ts, payment-signature.ts |\n| T16 | Card data in our database | not stored at all: only method name and amount | payments table |\n\n### The bank side of the webhook\n\n- `scripts/bank-simulator.mjs` plays the bank: it signs the exact bytes of the body and sends\n  10 scenarios (no signature, wrong secret, body changed after signing, 10-minute-old request,\n  wrong amount, unknown payment, ignored event type, real payment, the same event again, a new\n  event for an already paid payment) and prints PASS/FAIL. With `--previous-secret` it also checks rotation.\n- `PAYMENT_WEBHOOK_SCHEME` chooses how the bank sends the signature: `voronix` (two headers) or\n  `stripe` (one `stripe-signature: t=...,v1=...` header, several `v1` allowed). A real bank with\n  another format gets one more branch in `readSignatureHeaders`; the checking does not change.\n- Secret rotation: set the new secret as `PAYMENT_WEBHOOK_SECRET` and keep the old one as\n  `PAYMENT_WEBHOOK_SECRET_PREVIOUS` until the bank has switched; then remove it.\n\nNot done yet: the signature format and field names of the REAL bank (they come from the bank's\ndocumentation and a merchant contract, not from us), a per-business secret instead of one\n`PAYMENT_WEBHOOK_SECRET`, and the web page sending `Idempotency-Key` (`crypto.randomUUID()` once\nper button press).\n",
  "overwrite": true
 },
 "scripts/bank-simulator.mjs": {
  "content": "#!/usr/bin/env node\n// scripts/bank-simulator.mjs  -- plays the BANK for the payment webhook, so the CRM side can be\n// tested (and shown to the teacher) without a real bank. No packages needed, Node 18+.\n//\n//   node scripts/bank-simulator.mjs --business <business uuid> --payment PM-00001 --amount 6600\n//\n// Optional: --url http://localhost:3000  --secret <PAYMENT_WEBHOOK_SECRET>  --scheme voronix|stripe\n//           --previous-secret <old secret>   (checks secret rotation; the server must have it as\n//                                             PAYMENT_WEBHOOK_SECRET_PREVIOUS)\n// The server must run with PAYMENT_WEBHOOK_SECRET set. Use a Pending payment with its real amount.\nimport { createHmac, randomUUID } from \"node:crypto\";\n\nconst args = Object.fromEntries(\n  process.argv.slice(2).reduce((acc, cur, i, all) => (cur.startsWith(\"--\") ? [...acc, [cur.slice(2), all[i + 1]]] : acc), []),\n);\nconst url = args.url ?? \"http://localhost:3000\";\nconst secret = args.secret ?? process.env.PAYMENT_WEBHOOK_SECRET;\nconst scheme = args.scheme ?? \"voronix\";\nconst { business, payment } = args;\nconst amount = Number(args.amount);\nif (!business || !payment || !Number.isInteger(amount) || amount <= 0 || !secret) {\n  console.error(\"Need --business, --payment, --amount and the secret (--secret or PAYMENT_WEBHOOK_SECRET).\");\n  process.exit(2);\n}\nconst endpoint = `${url}/api/channels/${business}/payments/webhook`;\n\nconst sign = (key, ts, body) => createHmac(\"sha256\", key).update(`${ts}.`).update(body).digest(\"hex\");\nconst nowSec = () => Math.floor(Date.now() / 1000);\nconst eventId = () => `evt_${randomUUID().slice(0, 12)}`;\nconst event = (over = {}) => ({ event_id: eventId(), type: \"payment.succeeded\", payment_id: payment, amount_kzt: amount, ...over });\n\n/** What the bank does: serialise, sign the exact bytes, send. `tamper` changes the body AFTER signing. */\nasync function send(obj, { key = secret, ts = nowSec(), tamper, unsigned } = {}) {\n  const body = JSON.stringify(obj);\n  const headers = { \"content-type\": \"application/json\" };\n  if (!unsigned) {\n    const sig = sign(key, String(ts), body);\n    if (scheme === \"stripe\") headers[\"stripe-signature\"] = `t=${ts},v1=${sig}`;\n    else {\n      headers[\"x-voronix-timestamp\"] = String(ts);\n      headers[\"x-voronix-signature\"] = sig;\n    }\n  }\n  const res = await fetch(endpoint, { method: \"POST\", headers, body: tamper ? tamper(body) : body });\n  const text = await res.text();\n  let json = {};\n  try { json = JSON.parse(text); } catch { /* not JSON */ }\n  return { status: res.status, json };\n}\n\nconst repeated = event(); // the same event is sent twice later\nconst scenarios = [\n  [\"no signature at all\", () => send(event(), { unsigned: true }), 401],\n  [\"signed with a wrong secret\", () => send(event(), { key: \"not-the-secret\" }), 401],\n  [\"body changed after signing (amount 1)\", () => send(event(), { tamper: (b) => b.replace(String(amount), \"1\") }), 401],\n  [\"old request replayed (10 minutes old, signature is valid)\", () => send(event(), { ts: nowSec() - 600 }), 401],\n  [\"valid signature, but the amount is not the payment's amount\", () => send(event({ amount_kzt: amount + 1 })), 422],\n  [\"valid signature, payment does not exist\", () => send(event({ payment_id: \"PM-99999\" })), 404],\n  [\"other event type is ignored\", () => send(event({ type: \"payment.created\" })), 200, \"ignored\"],\n  [\"payment succeeded (the real one)\", () => send(repeated), 200, \"processed\"],\n  [\"the SAME event sent again (bank retry)\", () => send(repeated), 200, \"duplicate\"],\n  [\"a NEW event for an already paid payment (no double payment)\", () => send(event()), 200, \"processed\"],\n];\nif (args[\"previous-secret\"]) {\n  scenarios.push([\"signed with the previous secret (rotation window)\", () => send(event(), { key: args[\"previous-secret\"] }), 200, \"processed\"]);\n}\n\nlet failed = 0;\nconsole.log(`Bank simulator -> ${endpoint}  (scheme: ${scheme})\\n`);\nfor (const [name, run, wantStatus, wantBody] of scenarios) {\n  let got;\n  try {\n    got = await run();\n  } catch (err) {\n    got = { status: 0, json: { message: String(err.message ?? err) } };\n  }\n  const ok = got.status === wantStatus && (wantBody === undefined || got.json.status === wantBody);\n  if (!ok) failed++;\n  const want = wantBody ? `${wantStatus} ${wantBody}` : String(wantStatus);\n  const had = got.json.status ? `${got.status} ${got.json.status}` : String(got.status);\n  console.log(`${ok ? \"PASS\" : \"FAIL\"}  ${name}\\n      expected ${want}, got ${had}${ok ? \"\" : \"  \" + JSON.stringify(got.json)}`);\n}\nconsole.log(`\\n${scenarios.length - failed}/${scenarios.length} passed`);\nprocess.exit(failed ? 1 : 0);\n",
  "overwrite": false
 }
};
const BOOKING_BLOCK = "/** Fingerprint of what a request asked for: the same key with another body must not reuse the old answer. */\nfunction requestHash(parts: Record<string, unknown>): string {\n  return createHash(\"sha256\").update(JSON.stringify(parts)).digest(\"hex\");\n}\n\n/** The answer saved for this Idempotency-Key, or null when the key is new. */\nasync function replayOf(c: PgClient, key: string, operation: \"pay\" | \"refund\", paymentId: string, hash: string): Promise<Payment | null> {\n  const { rows } = await c.query<{ operation: string; payment_id: string; request_hash: string; response: Payment }>(\n    `SELECT operation, payment_id, request_hash, response FROM payment_requests WHERE idempotency_key = $1`,\n    [key],\n  );\n  const seen = rows[0];\n  if (!seen) return null;\n  if (seen.operation !== operation || seen.payment_id !== paymentId || seen.request_hash !== hash) {\n    throw new HttpError(422, \"This Idempotency-Key was already used for a different request.\", \"idempotency_conflict\");\n  }\n  return seen.response;\n}\n\nasync function rememberRequest(c: PgClient, key: string, operation: \"pay\" | \"refund\", paymentId: string, hash: string, response: Payment): Promise<void> {\n  await c.query(\n    `INSERT INTO payment_requests (idempotency_key, operation, payment_id, request_hash, response) VALUES ($1, $2, $3, $4, $5::jsonb)`,\n    [key, operation, paymentId, hash, JSON.stringify(response)],\n  );\n}\n\n/**\n * The client paid. One transaction: payment -> Paid, visit -> Confirmed,\n * the chat's deal -> Paid, and a note in the chat. Returns the chats to notify.\n * With an idempotency key a repeated request returns the first answer and changes nothing.\n */\nexport async function markPaid(\n  paymentId: string,\n  method = defaultPayMethod(),\n  db = pool,\n  idempotencyKey?: string,\n): Promise<{ payment: Payment; conversations: string[] }> {\n  let fresh = false;\n  const result = await tx(async (c) => {\n    // FOR UPDATE: parallel requests for the same payment wait here, one after another.\n    const p = await pays.getPayment(c, paymentId, true);\n    if (!p) throw notFound(\"Payment\");\n    const hash = requestHash({ op: \"pay\", paymentId, method });\n    if (idempotencyKey) {\n      const earlier = await replayOf(c, idempotencyKey, \"pay\", paymentId, hash);\n      if (earlier) return { payment: earlier, conversations: [] as string[] };\n    }\n    if (p.status === \"Refunded\") throw conflict(\"This payment was refunded.\");\n    if (p.status === \"Paid\") {\n      if (idempotencyKey) await rememberRequest(c, idempotencyKey, \"pay\", paymentId, hash, p);\n      return { payment: p, conversations: [] as string[] };\n    }\n    const paid = (await pays.setPaymentStatus(c, paymentId, \"Paid\", method))!;\n    fresh = true;\n    await c.query(`UPDATE appointments SET status = 'Confirmed' WHERE appointment_id = $1 AND status = 'Booked'`, [p.appointment_id]);\n    const { rows } = await c.query<{ id: string }>(\n      `UPDATE conversations SET stage = 'Paid', updated_at = now() WHERE appointment_id = $1 RETURNING conversation_id AS id`,\n      [p.appointment_id],\n    );\n    for (const r of rows) await convs.addMessage(c, r.id, { from: \"system\", text: `Payment received: ${money(paid.amount_kzt)} (${method}). Booking confirmed.` });\n    if (idempotencyKey) await rememberRequest(c, idempotencyKey, \"pay\", paymentId, hash, paid);\n    return { payment: paid, conversations: rows.map((r) => r.id) };\n  }, db);\n  bus.changed(\"payments\", \"appointments\", \"conversations\");\n  if (fresh) bus.publish({ type: \"domain\", name: \"payment.paid\", data: { ...result.payment } });\n  return result;\n}\n\nexport interface RefundInput {\n  amount_kzt?: number; // without it the whole remaining amount is refunded\n  reason?: string;\n  by?: string; // id of the user who refunds\n  idempotencyKey?: string;\n}\n\n/**\n * Refund. A Paid payment gets a row in payment_refunds (partial refunds allowed, never more than\n * was paid, the database locks the payment row). A Pending payment was never paid, so it is\n * simply cancelled, as before.\n */\nexport async function refund(paymentId: string, input: RefundInput = {}, db = pool): Promise<Payment> {\n  const result = await tx(async (c) => {\n    const p = await pays.getPayment(c, paymentId, true);\n    if (!p) throw notFound(\"Payment\");\n    const hash = requestHash({ op: \"refund\", paymentId, amount: input.amount_kzt ?? null, reason: input.reason ?? null });\n    if (input.idempotencyKey) {\n      const earlier = await replayOf(c, input.idempotencyKey, \"refund\", paymentId, hash);\n      if (earlier) return earlier;\n    }\n    let out: Payment;\n    if (p.status === \"Pending\") {\n      out = (await pays.setPaymentStatus(c, paymentId, \"Refunded\"))!;\n    } else {\n      const { rows } = await c.query<{ done: number }>(\n        `SELECT COALESCE(SUM(amount_kzt), 0)::int AS done FROM payment_refunds WHERE payment_id = $1`,\n        [paymentId],\n      );\n      const left = Number(p.amount_kzt) - (rows[0]?.done ?? 0);\n      if (p.status === \"Refunded\" || left <= 0) throw conflict(\"This payment is already fully refunded.\");\n      const amount = input.amount_kzt ?? left;\n      if (amount > left) throw conflict(`Only ${left} can still be refunded for this payment.`);\n      await c.query(\n        `INSERT INTO payment_refunds (payment_id, amount_kzt, reason, refunded_by) VALUES ($1, $2, $3, $4)`,\n        [paymentId, amount, input.reason ?? \"Refund\", input.by ?? \"system\"],\n      );\n      out = (await pays.getPayment(c, paymentId, false))!; // the database closed it as Refunded if the sum is complete\n    }\n    if (input.idempotencyKey) await rememberRequest(c, input.idempotencyKey, \"refund\", paymentId, hash, out);\n    return out;\n  }, db);\n  bus.changed(\"payments\");\n  return result;\n}\n\n";

const writes = new Map(); // absolute path -> final text (with the file's own line endings)
const report = [];

function die(msg) {
  console.error("\nSTOP, nothing was changed: " + msg);
  process.exit(1);
}
function load(rel) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) die(`${rel} not found. Run the script from the project root (the folder with package.json).`);
  const raw = fs.readFileSync(p, "utf8");
  return { p, rel, crlf: raw.includes("\r\n"), text: raw.replace(/\r\n/g, "\n") };
}
function save(f, text) {
  writes.set(f.p, f.crlf ? text.replace(/\n/g, "\r\n") : text);
}
function replaceOnce(text, from, to, label) {
  const i = text.indexOf(from);
  if (i < 0) die(`${label}: the place to edit was not found:\n  ${from.split("\n")[0].slice(0, 90)}\nSend me this part of the file.`);
  if (text.indexOf(from, i + 1) >= 0) die(`${label}: the place to edit is not unique.`);
  return text.slice(0, i) + to + text.slice(i + from.length);
}
function edit(rel, fn) {
  const f = load(rel);
  const before = f.text;
  const after = fn(f.text);
  if (after !== before) {
    save(f, after);
    report.push("edited   " + rel);
  } else report.push("already  " + rel);
}

// ---- 1. new files -------------------------------------------------------------------------
for (const [rel, file] of Object.entries(NEW_FILES)) {
  const p = path.join(root, rel);
  if (fs.existsSync(p)) {
    const old = fs.readFileSync(p, "utf8").replace(/\r\n/g, "\n");
    if (old === file.content) { report.push("same     " + rel); continue; }
    if (!file.overwrite) die(`${rel} already exists with other content. Remove it or tell me.`);
    if (rel.endsWith("crm.routes.ts") && !(old.includes("export const crmRouter") && old.includes('crmRouter.delete("/knowledge/:id"'))) {
      die("apps/api/src/routes/crm.routes.ts is not the file I saw. Send me its content.");
    }
    const crlf = fs.readFileSync(p, "utf8").includes("\r\n");
    writes.set(p, crlf ? file.content.replace(/\n/g, "\r\n") : file.content);
    report.push("replaced " + rel);
  } else {
    writes.set(p, file.content);
    report.push("created  " + rel);
  }
}

// ---- 2. app.ts -----------------------------------------------------------------------------
edit("apps/api/src/app.ts", (t) => {
  if (!t.includes('from "./auth/rbac.js"'))
    t = replaceOnce(t, 'import { requireAuth } from "./auth/auth.service.js";\n', 'import { requireAuth } from "./auth/auth.service.js";\nimport { requirePermission } from "./auth/rbac.js";\n', "app.ts imports");
  if (!t.includes("payment-webhook.routes"))
    t = replaceOnce(t, 'import { requirePermission } from "./auth/rbac.js";\n', 'import { requirePermission } from "./auth/rbac.js";\nimport { paymentWebhookRouter } from "./routes/payment-webhook.routes.js";\n', "app.ts webhook import");
  if (!t.includes('requirePermission("integrations:manage")'))
    t = replaceOnce(
      t,
      "  app.use(requireAuth);\n",
      '  app.use(requireAuth);\n  // Role checks for whole areas: integrations, SQL console and import are not for every role.\n' +
        '  app.use("/api/integrations", requirePermission("integrations:manage"));\n' +
        '  app.use("/api/sql", requirePermission("sql:console"));\n' +
        '  app.use("/api/import", requirePermission("import:manage"));\n',
      "app.ts role guards",
    );
  if (!t.includes("crmRouter, paymentWebhookRouter"))
    t = replaceOnce(t, "crmRouter, conversationsRouter, metaRouter", "crmRouter, paymentWebhookRouter, conversationsRouter, metaRouter", "app.ts router list");
  return t;
});

