  if (!t.includes('"accountant"'))
    t = replaceOnce(t, 'role: "owner" | "admin" | "staff";', 'role: "owner" | "admin" | "accountant" | "master" | "staff";\n  master_id?: string | null;', "auth.repo.ts role type");
  if (!t.includes("u.master_id")) t = replaceOnce(t, "u.full_name, u.role`", "u.full_name, u.role, u.master_id`", "auth.repo.ts USER columns");
