edit("apps/api/src/db/seed.ts", (t) => {
  if (!t.includes("payment_refunds"))
    t = replaceOnce(t, "conversations, payments, appointments", "conversations, payment_events, payment_requests, payment_refunds, payments, appointments", "seed.ts TRUNCATE");
  return t;
});

// ---- 5. booking.service.ts -----------------------------------------------------------------
edit("apps/api/src/services/booking.service.ts", (t) => {
  if (t.includes("function replayOf")) return t;
  const start = t.indexOf("/**\n * The client paid.");
  const end = t.indexOf("/** Full payment taken at the desk. */");
  if (start < 0 || end < 0 || end < start) die("booking.service.ts: cannot find the markPaid ... refund block. Send me lines 150-190 of the file.");
  t = t.slice(0, start) + BOOKING_BLOCK + t.slice(end);
  let head = "";
  if (!/import[^;]*\bcreateHash\b/.test(t)) head += 'import { createHash } from "node:crypto";\n';
  if (!/import[^;]*\bPgClient\b/.test(t)) head += 'import type { PoolClient as PgClient } from "pg";\n';
  if (!/import[^;]*\bHttpError\b/.test(t)) head += 'import { HttpError } from "../lib/errors.js";\n';
  return head + t;
});

// ---- 6. database.test.ts -------------------------------------------------------------------
edit("apps/api/test/integration/database.test.ts", (t) => {
  if (!t.includes("002_roles.sql")) t = replaceOnce(t, '["001_accounts.sql"]', '["001_accounts.sql", "002_roles.sql"]', "database.test.ts core list");
  if (!t.includes("009_payments_security.sql")) {
    if (t.includes('"008_security_audit.sql"]')) t = replaceOnce(t, '"008_security_audit.sql"]', '"008_security_audit.sql", "009_payments_security.sql"]', "database.test.ts tenant list");
    else t = replaceOnce(t, '"007_ai_engine.sql"]', '"007_ai_engine.sql", "008_security_audit.sql", "009_payments_security.sql"]', "database.test.ts tenant list");
  }
  if (!t.includes('"payment_events"')) {
    const withAudit = t.includes('"audit_log"');
    t = replaceOnce(t, '"messages", "payments", "services"', '"messages", "payment_events", "payment_refunds", "payment_requests", "payments", "services"', "database.test.ts table list");
    if (!withAudit) t = replaceOnce(t, '"appointments", "business_settings"', '"appointments", "audit_log", "business_settings"', "database.test.ts audit_log");
  }
  t = t.replace(/has the \d+ CRM tables/, "has the 19 CRM tables");
  return t;
});

// ---- 7. .env.example -----------------------------------------------------------------------
edit(".env.example", (t) => {
  let add = "";
  if (!t.includes("PAYMENT_WEBHOOK_SECRET="))
    add += "\n# Secret shared with the payment provider: payment webhooks are signed with it (HMAC-SHA256).\n# Generate: node -e \"console.log(require('node:crypto').randomBytes(32).toString('hex'))\"\nPAYMENT_WEBHOOK_SECRET=\n";
  if (!t.includes("PAYMENT_WEBHOOK_SECRET_PREVIOUS"))
    add += "\n# While the secret is rotated, the old one stays valid here; remove it when the bank has switched.\nPAYMENT_WEBHOOK_SECRET_PREVIOUS=\n# How the bank sends the signature: voronix (two headers) or stripe (one stripe-signature header).\nPAYMENT_WEBHOOK_SCHEME=voronix\n";
  return add ? t.replace(/\n*$/, "\n") + add : t;
});

// ---- write everything ----------------------------------------------------------------------
for (const [p, text] of writes) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text, "utf8");
}
console.log(report.join("\n"));
console.log("\nDone. Next: npm run db:migrate, then the check scripts and npm test. Delete apply-rbac-patch.mjs (do not commit it).");
